private void Rap_MarzhiShitjeve_SipasGrupimArtikujve_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) 
{
      var parameters = AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]);
      var formati = parameters.Find(param => param.Emri == "filterFormatNumri");
	string shifraPasPresjes = (formati != null) ? formati.Vlera : "2";	
	AlphaWebReports.raporteUtil.vendosFormatinEFushesSeRaportit("{0:N"+shifraPasPresjes+"}",0.ToString("N" + shifraPasPresjes), true,
			xrLabel1 , xrLabel2 , xrLabel3 , xrLabel4 , xrLabel5, xrLabel6 , xrLabel7, xrLabel34 , xrLabel35, xrLabel36 , xrLabel37, xrLabel38,
			xrLabel39 , xrLabel40 , xrLabel31 , KMSHTotali , VleraMeZbritjeTotali , MarzhiMeZbritjeTotali , MarzhiPerqindjeTotali);
xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);
}
